  });

  const guide = Option.getOrNull(decodeGuide(envelope.guide));
  const guideRepeats =
    guide === null ||
    [...guide.whatStoodOut, ...guide.whatPeopleRaised, ...guide.actionsToCheckOn, ...guide.questions].some(
